1	//! The unions a file writes for its props, member by member in written order (ADR 0026, S7a2).
2	//!
3	//! The checker returns a union's members sorted by kind, then value, and the order the author wrote is the order a
4	//! Storybook control lists the options in. This reads it from the syntax alone: the union a property signature writes,
5	//! directly or through a type alias or enum the same file declares at module level. A name the file does not declare
6	//! (an import, a global, a type reached through a namespace) is kept as the name: what it stands for is in another
7	//! file, which oxc cannot find without resolving modules.
8	//!
9	//! A name is expanded only where it is the declaration in scope: a type parameter or a type an enclosing namespace,
10	//! function or block declares shadows the module-level one, and the name stays as written. An alias is expanded once
11	//! per file, in the module scope it is declared in, and a union past [`MAX_WRITTEN_MEMBERS`] is not read at all.
12	
13	use std::cell::RefCell;
14	use std::rc::Rc;
15	
16	use compact_str::CompactString;
17	use oxc_allocator::Allocator;
18	use oxc_ast::ast::*;
19	use oxc_ast_visit::{Visit, walk};
20	use oxc_parser::{ParseOptions, Parser};
21	use oxc_span::{SourceType, Span};
22	use rustc_hash::{FxHashMap, FxHashSet};
23	
24	use super::js_text;
25	use crate::types::output::{BigIntValue, PropType, TupleElement};
26	
27	/// The most members a written union may state, counting those of every alias it names. Past it the union is not read,
28	/// so the work an alias graph can ask for stays bounded.
29	pub(crate) const MAX_WRITTEN_MEMBERS: usize = 1024;
30	
31	/// The property signatures of one file whose written type is a union of at least two members.
32	#[derive(Debug, Default)]
33	pub(crate) struct WrittenUnions {
34	    props: Vec<WrittenProp>,
35	    /// How many property signatures write a union past [`MAX_WRITTEN_MEMBERS`] and were not read.
36	    pub(crate) declined: usize,
37	}
38	
39	#[derive(Debug)]
40	struct WrittenProp {
41	    owner: Owner,
42	    name: CompactString,
43	    members: Vec<WrittenMember>,
44	}
45	
46	/// What a property signature is a member of, as the syntax shows it.
47	#[derive(Debug, Clone, PartialEq, Eq)]
48	pub(crate) enum Owner {
49	    /// The body of the interface of this name, wherever it is declared.
50	    Interface(CompactString),
51	    /// A type literal that is the body of the module-level alias of this name, or a member of the intersection or union
52	    /// that body is.
53	    Alias(CompactString),
54	    /// A type literal written in an annotation outside every declaration's body (a component's parameter, a
55	    /// `forwardRef` type argument), starting at this byte offset.
56	    Annotation(u32),
57	    /// A type literal anywhere else: in a function body, a namespace, a class body or another type's arguments.
58	    Elsewhere,
59	}
60	
61	/// One member of a written union, as far as the file states it.
62	#[derive(Debug, Clone, PartialEq)]
63	pub(crate) enum WrittenMember {
64	    /// A member the syntax states in full: a literal, a keyword, an array or tuple of those.
65	    Type(PropType),
66	    /// A reference to a type the file does not declare, as written (`React.ReactNode`, `Size.Small` for a member of an
67	    /// enum the file declares).
68	    Name(CompactString),
69	    /// A member of which only the kind is written: a function type, an object literal, an intersection.
70	    Kind(MemberKind),
71	}
72	
73	/// The kind of a union member whose type is not written out in full.
74	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
75	pub(crate) enum MemberKind {
76	    Function,
77	    Object,
78	    Callable,
79	    Array,
80	    Tuple,
81	    Readonly,
82	    Intersection,
83	    Template,
84	}
85	
86	impl WrittenUnions {
87	    /// The union written for prop `name` by the declarations `held` accepts the owner of: the one every such
88	    /// declaration writes alike, or `None` when there is none or two write different unions.
89	    pub(crate) fn find(&self, name: &str, held: impl Fn(&Owner) -> bool) -> Option<&[WrittenMember]> {
90	        let mut found =
91	            self.props.iter().filter(|prop| prop.name == name && held(&prop.owner)).map(|prop| prop.members.as_slice());
92	        let first = found.next()?;
93	        found.all(|other| other == first).then_some(first)
94	    }
95	}
96	
97	/// The written unions of `source`, the text of `path`. Empty for a file too deeply nested to parse safely.
98	pub(crate) fn written_unions(path: &camino::Utf8Path, source: &str) -> WrittenUnions {
99	    if super::max_bracket_nesting_depth(source) > super::MAX_SOURCE_NESTING_DEPTH {
100	        return WrittenUnions::default();
101	    }
102	    let allocator = Allocator::default();
103	    let source_type = SourceType::from_path(path).unwrap_or_default();
104	    let options = ParseOptions { preserve_parens: false, ..ParseOptions::default() };
105	    let parsed = Parser::new(&allocator, source, source_type).with_options(options).parse();
106	    let mut collector = Collector {
107	        declared: Declared::of(&parsed.program),
108	        owner: None,
109	        member_depth: 0,
110	        body_depth: 0,
111	        alias_literals: Vec::new(),
112	        shadows: Vec::new(),
113	        expansions: RefCell::default(),
114	        unions: WrittenUnions::default(),
115	    };
116	    collector.visit_program(&parsed.program);
117	    collector.unions
118	}
119	
120	/// The module-level declarations a union member can name: a name declared twice is in `ambiguous` and expands to
121	/// nothing.
122	#[derive(Default)]
123	struct Declared<'a, 's> {
124	    aliases: FxHashMap<&'s str, &'s TSTypeAliasDeclaration<'a>>,
125	    interfaces: FxHashSet<&'s str>,
126	    enums: FxHashMap<&'s str, Vec<CompactString>>,
127	    ambiguous: Vec<&'s str>,
128	}
129	
130	impl<'a, 's> Declared<'a, 's> {
131	    fn of(program: &'s Program<'a>) -> Self {
132	        let mut declared = Declared::default();
133	        for statement in &program.body {
134	            let declaration = match statement {
135	                Statement::ExportDeclaration(export) => Some(&export.declaration),
136	                _ => statement.as_declaration(),
137	            };
138	            match declaration {
139	                Some(Declaration::TSTypeAliasDeclaration(alias)) => {
140	                    let name = alias.id.name.as_str();
141	                    if declared.aliases.insert(name, &**alias).is_some() {
142	                        declared.ambiguous.push(name);
143	                    }
144	                }
145	                Some(Declaration::TSInterfaceDeclaration(interface)) => {
146	                    declared.interfaces.insert(interface.id.name.as_str());
147	                }
148	                Some(Declaration::TSEnumDeclaration(declaration)) => {
149	                    let members = declaration
150	                        .body
151	                        .members
152	                        .iter()
153	                        .filter_map(|member| match &member.id {
154	                            TSEnumMemberName::Identifier(id) => Some(CompactString::from(id.name.as_str())),
155	                            TSEnumMemberName::String(s) | TSEnumMemberName::ComputedString(s) => {
156	                                Some(CompactString::from(js_text::lossy(s.value).as_ref()))
157	                            }
158	                            TSEnumMemberName::ComputedTemplateString(_) => None,
159	                        })
160	                        .collect();
161	                    let name = declaration.id.name.as_str();
162	                    if declared.enums.insert(name, members).is_some() {
163	                        declared.ambiguous.push(name);
164	                    }
165	                }
166	                _ => {}
167	            }
168	        }
169	        declared
170	    }
171	}
172	
173	/// Where a name in a written union is looked up.
174	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
175	enum Scope {
176	    /// At the property signature: the type parameters and the declarations of enclosing blocks shadow the module's.
177	    Prop,
178	    /// In a module-level alias's body, where only the module's declarations are in scope.
179	    Module,
180	}
181	
182	/// Why a union is not read.
183	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
184	enum Unread {
185	    /// It states more than [`MAX_WRITTEN_MEMBERS`] members.
186	    TooMany,
187	    /// An alias it names flattens into itself, which TypeScript rejects.
188	    Circular,
189	}
190	
191	/// What a module-level alias flattens to, once per file.
192	#[derive(Debug, Clone)]
193	enum Expansion {
194	    InProgress,
195	    Done(Result<Rc<[WrittenMember]>, Unread>),
196	}
197	
198	/// The members of one union as they are gathered: a member stated twice is one member (`U | U` is `U`), and an alias
199	/// already flattened into it adds nothing again.
200	#[derive(Default)]
201	struct Members<'s> {
202	    list: Vec<WrittenMember>,
203	    aliases: Vec<&'s str>,
204	}
205	
206	impl Members<'_> {
207	    fn push(&mut self, member: WrittenMember) -> Result<(), Unread> {
208	        match &member {
209	            // Two members written by kind can be two different types.
210	            WrittenMember::Kind(_) => {}
211	            WrittenMember::Type(_) | WrittenMember::Name(_) => {
212	                if self.list.contains(&member) {
213	                    return Ok(());
214	                }
215	            }
216	        }
217	        if self.list.len() == MAX_WRITTEN_MEMBERS {
218	            return Err(Unread::TooMany);
219	        }
220	        self.list.push(member);
221	        Ok(())
222	    }
223	}
224	
225	struct Collector<'a, 's> {
226	    declared: Declared<'a, 's>,
227	    /// What the property signatures being read are members of.
228	    owner: Option<Owner>,
229	    /// How many property signatures enclose the current node: a member of a type literal nested in another member's
230	    /// type is not a prop.
231	    member_depth: usize,
232	    /// How many declaration bodies enclose the current node (an interface's, an alias's, a function's, a class's, a
233	    /// namespace's, a block): a type literal outside all of them is written in an annotation.
234	    body_depth: usize,
235	    /// The type literals that make up the body of the module-level alias being read, with its name.
236	    alias_literals: Vec<(Span, CompactString)>,
237	    /// The names in scope that shadow a module-level declaration: type parameters, and the types enclosing namespaces,
238	    /// functions and blocks declare.
239	    shadows: Vec<CompactString>,
240	    expansions: RefCell<FxHashMap<&'s str, Expansion>>,
241	    unions: WrittenUnions,
242	}
243	
244	impl<'a, 's> Visit<'a> for Collector<'a, 's> {
245	    fn visit_ts_interface_declaration(&mut self, it: &TSInterfaceDeclaration<'a>) {
246	        let scope = self.enter_type_params(it.type_parameters.as_deref());
247	        let owner = self.owner.replace(Owner::Interface(CompactString::from(it.id.name.as_str())));
248	        self.body_depth += 1;
249	        walk::walk_ts_interface_declaration(self, it);
250	        self.body_depth -= 1;
251	        self.owner = owner;
252	        self.shadows.truncate(scope);
253	    }
254	
255	    fn visit_ts_type_alias_declaration(&mut self, it: &TSTypeAliasDeclaration<'a>) {
256	        let scope = self.enter_type_params(it.type_parameters.as_deref());
257	        let literals = self.alias_literals.len();
258	        let name = it.id.name.as_str();
259	        let module_level = self.body_depth == 0
260	            && !self.declared.ambiguous.contains(&name)
261	            && self.declared.aliases.get(name).is_some_and(|alias| std::ptr::eq(*alias, it));
262	        if module_level {
263	            let mut spans = Vec::new();
264	            body_literals(&it.type_annotation, &mut spans);
265	            self.alias_literals.extend(spans.into_iter().map(|span| (span, CompactString::from(name))));
266	        }
267	        self.body_depth += 1;
268	        walk::walk_ts_type_alias_declaration(self, it);
269	        self.body_depth -= 1;
270	        self.alias_literals.truncate(literals);
271	        self.shadows.truncate(scope);
272	    }
273	
274	    fn visit_function(&mut self, it: &Function<'a>, flags: oxc_syntax::scope::ScopeFlags) {
275	        let scope = self.enter_type_params(it.type_parameters.as_deref());
276	        walk::walk_function(self, it, flags);
277	        self.shadows.truncate(scope);
278	    }
279	
280	    fn visit_arrow_function_expression(&mut self, it: &ArrowFunctionExpression<'a>) {
281	        let scope = self.enter_type_params(it.type_parameters.as_deref());
282	        walk::walk_arrow_function_expression(self, it);
283	        self.shadows.truncate(scope);
284	    }
285	
286	    fn visit_class(&mut self, it: &Class<'a>) {
287	        let scope = self.enter_type_params(it.type_parameters.as_deref());
288	        walk::walk_class(self, it);
289	        self.shadows.truncate(scope);
290	    }
291	
292	    fn visit_class_body(&mut self, it: &ClassBody<'a>) {
293	        self.in_block([], |collector| walk::walk_class_body(collector, it));
294	    }
295	
296	    fn visit_function_body(&mut self, it: &FunctionBody<'a>) {
297	        self.in_block(&it.statements, |collector| walk::walk_function_body(collector, it));
298	    }
299	
300	    fn visit_ts_module_block(&mut self, it: &TSModuleBlock<'a>) {
301	        self.in_block(&it.body, |collector| walk::walk_ts_module_block(collector, it));
302	    }
303	
304	    fn visit_block_statement(&mut self, it: &BlockStatement<'a>) {
305	        self.in_block(&it.body, |collector| walk::walk_block_statement(collector, it));
306	    }
307	
308	    fn visit_static_block(&mut self, it: &StaticBlock<'a>) {
309	        self.in_block(&it.body, |collector| walk::walk_static_block(collector, it));
310	    }
311	
312	    fn visit_switch_statement(&mut self, it: &SwitchStatement<'a>) {
313	        let cases = it.cases.iter().flat_map(|case| &case.consequent);
314	        self.in_block(cases, |collector| walk::walk_switch_statement(collector, it));
315	    }
316	
317	    fn visit_ts_type_literal(&mut self, it: &TSTypeLiteral<'a>) {
318	        let holder = match self.alias_literals.iter().find(|(span, _)| *span == it.span) {
319	            Some((_, alias)) => Owner::Alias(alias.clone()),
320	            None if self.body_depth == 0 => Owner::Annotation(it.span.start),
321	            None => Owner::Elsewhere,
322	        };
323	        let owner = self.owner.replace(holder);
324	        walk::walk_ts_type_literal(self, it);
325	        self.owner = owner;
326	    }
327	
328	    fn visit_ts_property_signature(&mut self, it: &TSPropertySignature<'a>) {
329	        if self.member_depth == 0
330	            && let Some(owner) = &self.owner
331	            && let Some(name) = it.key.static_name()
332	            && let Some(annotation) = &it.type_annotation
333	        {
334	            let mut members = Members::default();
335	            match self.push_members(&annotation.type_annotation, Scope::Prop, &mut members) {
336	                Ok(()) if members.list.len() > 1 => self.unions.props.push(WrittenProp {
337	                    owner: owner.clone(),
338	                    name: CompactString::from(js_text::property_name(&name)),
339	                    members: members.list,
340	                }),
341	                Ok(()) | Err(Unread::Circular) => {}
342	                Err(Unread::TooMany) => self.unions.declined += 1,
343	            }
344	        }
345	        self.member_depth += 1;
346	        walk::walk_ts_property_signature(self, it);
347	        self.member_depth -= 1;
348	    }
349	}
