351	impl<'a, 's> Collector<'a, 's> {
352	    fn enter_type_params(&mut self, params: Option<&TSTypeParameterDeclaration<'a>>) -> usize {
353	        let scope = self.shadows.len();
354	        for param in params.into_iter().flat_map(|params| &params.params) {
355	            self.shadows.push(CompactString::from(param.name.name.as_str()));
356	        }
357	        scope
358	    }
359	
360	    /// Walks a body whose `statements` may declare types that shadow the module's.
361	    fn in_block<'b>(&mut self, statements: impl IntoIterator<Item = &'b Statement<'a>>, walk: impl FnOnce(&mut Self))
362	    where
363	        'a: 'b,
364	    {
365	        let scope = self.shadows.len();
366	        self.shadows.extend(statements.into_iter().filter_map(declared_type));
367	        self.body_depth += 1;
368	        walk(self);
369	        self.body_depth -= 1;
370	        self.shadows.truncate(scope);
371	    }
372	
373	    /// A module-level declaration named `name` that nothing in `scope` shadows and no other declaration shares.
374	    fn declares(&self, name: &str, scope: Scope) -> bool {
375	        let shadowed = match scope {
376	            Scope::Prop => self.shadows.iter().any(|shadow| shadow == name),
377	            Scope::Module => false,
378	        };
379	        !shadowed && !self.declared.ambiguous.contains(&name)
380	    }
381	
382	    /// Adds the members `ty` writes to `out`, flattening a union and a same-file non-generic alias or enum it names.
383	    fn push_members(&self, ty: &TSType<'a>, scope: Scope, out: &mut Members<'s>) -> Result<(), Unread> {
384	        match ty {
385	            TSType::TSUnionType(union) => {
386	                for member in &union.types {
387	                    self.push_members(member, scope, out)?;
388	                }
389	                Ok(())
390	            }
391	            TSType::TSParenthesizedType(inner) => self.push_members(&inner.type_annotation, scope, out),
392	            TSType::TSTypeReference(reference) => {
393	                if let TSTypeName::IdentifierReference(id) = &reference.type_name
394	                    && reference.type_arguments.is_none()
395	                    && self.declares(id.name.as_str(), scope)
396	                {
397	                    let name = id.name.as_str();
398	                    if let Some((&name, &alias)) = self.declared.aliases.get_key_value(name)
399	                        && alias.type_parameters.is_none()
400	                    {
401	                        if !out.aliases.contains(&name) {
402	                            out.aliases.push(name);
403	                            for member in self.expand(name, alias)?.iter() {
404	                                out.push(member.clone())?;
405	                            }
406	                        }
407	                        return Ok(());
408	                    }
409	                    if let Some(members) = self.declared.enums.get(name) {
410	                        for member in members {
411	                            out.push(WrittenMember::Name(format!("{name}.{member}").into()))?;
412	                        }
413	                        return Ok(());
414	                    }
415	                }
416	                self.member(ty, scope).map_or(Ok(()), |member| out.push(member))
417	            }
418	            _ => self.member(ty, scope).map_or(Ok(()), |member| out.push(member)),
419	        }
420	    }
421	
422	    /// The members the module-level alias `name` flattens to, read once per file in the module scope.
423	    fn expand(&self, name: &'s str, alias: &'s TSTypeAliasDeclaration<'a>) -> Result<Rc<[WrittenMember]>, Unread> {
424	        let known = self.expansions.borrow().get(name).cloned();
425	        match known {
426	            Some(Expansion::Done(done)) => return done,
427	            Some(Expansion::InProgress) => return Err(Unread::Circular),
428	            None => {}
429	        }
430	        self.expansions.borrow_mut().insert(name, Expansion::InProgress);
431	        let mut members = Members::default();
432	        let done =
433	            self.push_members(&alias.type_annotation, Scope::Module, &mut members).map(|()| Rc::from(members.list));
434	        self.expansions.borrow_mut().insert(name, Expansion::Done(done.clone()));
435	        done
436	    }
437	
438	    /// One member as written; `None` for a type the syntax does not state (`typeof x`, `keyof T`, an indexed access, a
439	    /// conditional or mapped type).
440	    fn member(&self, ty: &TSType<'a>, scope: Scope) -> Option<WrittenMember> {
441	        let written = |prop_type| Some(WrittenMember::Type(prop_type));
442	        let kind = |kind| Some(WrittenMember::Kind(kind));
443	        match ty {
444	            TSType::TSStringKeyword(_) => written(PropType::String),
445	            TSType::TSNumberKeyword(_) => written(PropType::Number),
446	            TSType::TSBooleanKeyword(_) => written(PropType::Boolean),
447	            TSType::TSNullKeyword(_) => written(PropType::Null),
448	            TSType::TSUndefinedKeyword(_) => written(PropType::Undefined),
449	            TSType::TSAnyKeyword(_) => written(PropType::Any),
450	            TSType::TSNeverKeyword(_) => written(PropType::Never),
451	            TSType::TSUnknownKeyword(_) => written(PropType::Unknown),
452	            TSType::TSVoidKeyword(_) => written(PropType::Void),
453	            TSType::TSBigIntKeyword(_) => written(PropType::BigInt),
454	            TSType::TSLiteralType(literal) => literal_type(&literal.literal).map(WrittenMember::Type),
455	            TSType::TSParenthesizedType(inner) => self.member(&inner.type_annotation, scope),
456	            TSType::TSArrayType(array) => match self.member(&array.element_type, scope) {
457	                Some(WrittenMember::Type(element)) => written(PropType::Array(Box::new(element))),
458	                _ => kind(MemberKind::Array),
459	            },
460	            TSType::TSTupleType(tuple) => {
461	                let elements: Option<Vec<TupleElement>> = tuple
462	                    .element_types
463	                    .iter()
464	                    .map(|element| match self.member(element.as_ts_type()?, scope) {
465	                        Some(WrittenMember::Type(element)) => Some(TupleElement::required(element)),
466	                        _ => None,
467	                    })
468	                    .collect();
469	                match elements {
470	                    Some(elements) => written(PropType::Tuple(elements)),
471	                    None => kind(MemberKind::Tuple),
472	                }
473	            }
474	            TSType::TSTypeOperatorType(operator) => match operator.operator {
475	                TSTypeOperatorOperator::Readonly => match self.member(&operator.type_annotation, scope) {
476	                    Some(WrittenMember::Type(inner)) => written(PropType::Readonly(Box::new(inner))),
477	                    _ => kind(MemberKind::Readonly),
478	                },
479	                TSTypeOperatorOperator::Keyof | TSTypeOperatorOperator::Unique => None,
480	            },
481	            TSType::TSFunctionType(_) | TSType::TSConstructorType(_) => kind(MemberKind::Function),
482	            TSType::TSTypeLiteral(_) | TSType::TSIntersectionType(_) | TSType::TSTemplateLiteralType(_) => {
483	                body_kind(ty).map(WrittenMember::Kind)
484	            }
485	            TSType::TSTypeReference(reference) => self.reference(reference, scope),
486	            TSType::TSUnionType(_)
487	            | TSType::TSObjectKeyword(_)
488	            | TSType::TSSymbolKeyword(_)
489	            | TSType::TSIntrinsicKeyword(_)
490	            | TSType::TSThisType(_)
491	            | TSType::TSTypeQuery(_)
492	            | TSType::TSIndexedAccessType(_)
493	            | TSType::TSConditionalType(_)
494	            | TSType::TSMappedType(_)
495	            | TSType::TSInferType(_)
496	            | TSType::TSImportType(_)
497	            | TSType::TSTypePredicate(_)
498	            | TSType::TSNamedTupleMember(_)
499	            | TSType::JSDocNullableType(_)
500	            | TSType::JSDocNonNullableType(_)
501	            | TSType::JSDocUnknownType(_) => None,
502	        }
503	    }
504	
505	    /// A reference that is not a same-file alias of a union: the kind of a same-file interface or generic alias, an
506	    /// array type by its standard name, else the name as written.
507	    fn reference(&self, reference: &TSTypeReference<'a>, scope: Scope) -> Option<WrittenMember> {
508	        let name = type_name(&reference.type_name);
509	        if let TSTypeName::IdentifierReference(id) = &reference.type_name
510	            && self.declares(id.name.as_str(), scope)
511	        {
512	            let name = id.name.as_str();
513	            if self.declared.interfaces.contains(name) {
514	                return Some(WrittenMember::Kind(MemberKind::Object));
515	            }
516	            if let Some(alias) = self.declared.aliases.get(name) {
517	                // A generic alias's members depend on its arguments, and a non-generic one named here is not flattened:
518	                // only the kind of its body is certain.
519	                return body_kind(&alias.type_annotation).map(WrittenMember::Kind);
520	            }
521	        }
522	        match name.as_str() {
523	            "Array" => Some(WrittenMember::Kind(MemberKind::Array)),
524	            "ReadonlyArray" => Some(WrittenMember::Kind(MemberKind::Readonly)),
525	            _ => Some(WrittenMember::Name(name)),
526	        }
527	    }
528	}
529	
530	/// The spans of the type literals that make up an alias's body: the body itself, or the members of the intersection or
531	/// union it is.
532	fn body_literals(ty: &TSType<'_>, out: &mut Vec<Span>) {
533	    match ty {
534	        TSType::TSTypeLiteral(literal) => out.push(literal.span),
535	        TSType::TSParenthesizedType(inner) => body_literals(&inner.type_annotation, out),
536	        TSType::TSIntersectionType(intersection) => {
537	            for member in &intersection.types {
538	                body_literals(member, out);
539	            }
540	        }
541	        TSType::TSUnionType(union) => {
542	            for member in &union.types {
543	                body_literals(member, out);
544	            }
545	        }
546	        _ => {}
547	    }
548	}
