550	/// The name of the type `statement` declares in its block, when it declares one.
551	fn declared_type(statement: &Statement<'_>) -> Option<CompactString> {
552	    let declaration = match statement {
553	        Statement::ExportDeclaration(export) => &export.declaration,
554	        _ => statement.as_declaration()?,
555	    };
556	    let name = match declaration {
557	        Declaration::TSTypeAliasDeclaration(alias) => &alias.id.name,
558	        Declaration::TSInterfaceDeclaration(interface) => &interface.id.name,
559	        Declaration::TSEnumDeclaration(declaration) => &declaration.id.name,
560	        Declaration::ClassDeclaration(class) => &class.id.as_ref()?.name,
561	        Declaration::TSImportEqualsDeclaration(import) => &import.id.name,
562	        Declaration::VariableDeclaration(_)
563	        | Declaration::FunctionDeclaration(_)
564	        | Declaration::TSExternalModuleDeclaration(_)
565	        | Declaration::TSNamespaceDeclaration(_)
566	        | Declaration::TSGlobalDeclaration(_) => return None,
567	    };
568	    Some(CompactString::from(name.as_str()))
569	}
570	
571	/// The kind of a type as written at its top level, without following a name.
572	fn body_kind(ty: &TSType<'_>) -> Option<MemberKind> {
573	    match ty {
574	        TSType::TSArrayType(_) => Some(MemberKind::Array),
575	        TSType::TSTupleType(_) => Some(MemberKind::Tuple),
576	        TSType::TSFunctionType(_) | TSType::TSConstructorType(_) => Some(MemberKind::Function),
577	        TSType::TSTypeLiteral(literal) => Some(
578	            if literal.members.iter().any(|member| {
579	                matches!(
580	                    member,
581	                    TSSignature::TSCallSignatureDeclaration(_) | TSSignature::TSConstructSignatureDeclaration(_)
582	                )
583	            }) {
584	                MemberKind::Callable
585	            } else {
586	                MemberKind::Object
587	            },
588	        ),
589	        TSType::TSIntersectionType(_) => Some(MemberKind::Intersection),
590	        TSType::TSTemplateLiteralType(_) => Some(MemberKind::Template),
591	        TSType::TSTypeOperatorType(operator) if operator.operator == TSTypeOperatorOperator::Readonly => {
592	            Some(MemberKind::Readonly)
593	        }
594	        TSType::TSParenthesizedType(inner) => body_kind(&inner.type_annotation),
595	        _ => None,
596	    }
597	}
598	
599	fn type_name(name: &TSTypeName<'_>) -> CompactString {
600	    match name {
601	        TSTypeName::IdentifierReference(id) => CompactString::from(id.name.as_str()),
602	        TSTypeName::QualifiedName(qualified) => {
603	            let mut text = type_name(&qualified.left);
604	            text.push('.');
605	            text.push_str(qualified.right.name.as_str());
606	            text
607	        }
608	        TSTypeName::ThisExpression(_) => CompactString::from("this"),
609	    }
610	}
611	
612	fn literal_type(literal: &TSLiteral<'_>) -> Option<PropType> {
613	    match literal {
614	        TSLiteral::StringLiteral(s) => Some(PropType::StringLiteral(js_text::lossy(s.value).into_owned())),
615	        TSLiteral::NumericLiteral(n) => Some(PropType::NumberLiteral(n.value)),
616	        TSLiteral::BooleanLiteral(b) => Some(PropType::BoolLiteral(b.value)),
617	        TSLiteral::BigIntLiteral(b) => BigIntValue::parse(b.value.as_str()).map(PropType::BigIntLiteral),
618	        TSLiteral::UnaryExpression(unary) => match (&unary.operator, &unary.argument) {
619	            (UnaryOperator::UnaryNegation, Expression::NumericLiteral(n)) => Some(PropType::NumberLiteral(-n.value)),
620	            (UnaryOperator::UnaryNegation, Expression::BigIntLiteral(b)) => {
621	                BigIntValue::parse(&format!("-{}", b.value.as_str())).map(PropType::BigIntLiteral)
622	            }
623	            _ => None,
624	        },
625	        TSLiteral::TemplateLiteral(template) if template.expressions.is_empty() => template
626	            .quasis
627	            .first()
628	            .and_then(|quasi| quasi.value.cooked.as_ref())
629	            .map(|cooked| PropType::StringLiteral(js_text::lossy(*cooked).into_owned())),
630	        TSLiteral::TemplateLiteral(_) => None,
631	    }
632	}
