796	    fn a_recursive_alias_stops_where_it_names_itself() {
797	        let file = written("type Json = string | null | Json[]\ninterface Props { p?: Json }");
798	        assert_eq!(
799	            in_interface(&file, "Props", "p"),
800	            Some(
801	                &[
802	                    WrittenMember::Type(PropType::String),
