                        mapping.param_defaults.entry(name.clone()).or_insert_with(|| default.clone());
                    }
                }
            }
            for (start, end, params) in &self.function_type_params {
                if *start >= mapping.span_start && *end <= mapping.span_end {
                    for param in params {
                        if !mapping.type_params.contains(param) {
                            mapping.type_params.push(param.clone());
                        }
                    }
                }
            }
        }
        let mut named_by_display_name = FxHashSet::default();
        for (obj_name, display_name) in self.pending_display_name_renames.drain(..) {
            if let Some(index) = self.data.component_mappings.iter().position(|m| m.is_binding_named(&obj_name)) {
                self.data.component_mappings[index].component_name = display_name;
                named_by_display_name.insert(index);
            }
        }
        self.name_by_the_export(&named_by_display_name);
        self.name_the_anonymous_default();
        self.data
    }

    /// A component its module exports under one name other than its own is reported under that name:
    /// `export { _Card as Card }` is `Card`. The one place that names a component after an export; the exports
    /// themselves are what identify it (ADR 0027). Left alone: a component with a `displayName`, one exported under
    /// its own name or under several others, a sub-component (reached through a path) and one whose export name
    /// another component already has.
    fn name_by_the_export(&mut self, named_by_display_name: &FxHashSet<usize>) {
        let mappings = &self.data.component_mappings;
        let renames: Vec<(usize, String)> = mappings
            .iter()
            .enumerate()
            .filter(|(index, mapping)| mapping.bound && !named_by_display_name.contains(index))
            .filter_map(|(index, mapping)| {
                let mut named = mapping.exports.iter().filter(|e| e.members.is_empty() && e.name != "default");
                let (export, None) = (named.next()?, named.next()) else { return None };
                let free = mappings.iter().all(|other| other.component_name != export.name);
                (free && export.name != mapping.component_name).then(|| (index, export.name.clone()))
            })
            .collect();
        let mut taken = FxHashSet::default();
        for (index, name) in renames {
            if taken.insert(name.clone()) {
                let mapping = &mut self.data.component_mappings[index];
                mapping.local_name = Some(std::mem::replace(&mut mapping.component_name, name));
            }
        }
    }

    /// `import { A } from "./a"; export { A }` re-exports `A` exactly like `export { A } from "./a"`, and
    /// `import * as a from "./a"; export { a as A }` like `export * as A from "./a"`; barrels and bundled typings
    /// (radix-ui's) use both spellings, and only the second names a source file to follow.
    fn promote_reexported_imports(&mut self) {
        for (index, local) in std::mem::take(&mut self.pending_local_exports) {
            let Some(binding) = self.data.imports.iter().find(|imp| imp.local_name.as_str() == local) else { continue };
            let crate::types::LexedExport::LocalDeclaration { name, is_type_only, .. } = &self.data.exports[index]
            else {
                continue;
            };
            if binding.exported_name.as_str() == "*" {
                self.data.exports[index] = crate::types::LexedExport::ReExportNamespace {
                    namespace: name.clone(),
                    source_specifier: binding.specifier.clone(),
                };
                continue;
        let local = match &node.declaration {
            ExportDefaultDeclarationKind::FunctionDeclaration(func) => func.id.as_ref().map(|id| id.name.as_str()),
            ExportDefaultDeclarationKind::ClassDeclaration(class) => class.id.as_ref().map(|id| id.name.as_str()),
            kind => match kind.as_expression().map(super::component::peel_expr) {
                Some(Expression::Identifier(id)) => Some(id.name.as_str()),
                _ => None,
            },
        };
        if let Some(name) = local {
            self.record_exported_local(name, "default");
            // `export default Tooltip`: the module's default is `Tooltip`, which `finish` turns into a re-export
            // when it is an import, as `export { Tooltip as default }` is.
            self.pending_local_exports.push((self.data.exports.len(), name.to_owned()));
            self.data.exports.push(LexedExport::LocalDeclaration {
                name: "default".to_owned(),
                is_type_only: false,
                declared_as: Some(name.to_owned()),
            });
        }
        // An anonymous default export has no binding name, so the component is named after its file, as
        // `try_anonymous_default_export_component` already does for `export default function(props: Props) {}`. It is
        // no binding, so its export is its own and a component of the file with that name is another.
        let mut is_a_component = false;
        if self.is_tsx {
            match &node.declaration {
                ExportDefaultDeclarationKind::FunctionDeclaration(func) if func.id.is_none() => {
                    self.try_anonymous_default_export_component(func);
                }
                ExportDefaultDeclarationKind::ClassDeclaration(class) if class.id.is_none() => {
                    if let Some(name) = super::component::pascal_case_from_file_stem(&self.file_path)
                        && let Some(mapping) = self.try_class_component(class, &name)
                    {
                        self.anonymous_default = Some(mapping.span_start);
                        self.data.component_mappings.push(mapping.without_binding());
                    }
                }
                // `export default (props: P) => …`, `export default memo(function Badge(…))`,
                // `export default forwardRef<El, P>(…)`: an expression, so the declarator rules apply.
                kind => {
                    if let (Some(expr), Some(name)) =
                        (kind.as_expression(), super::component::pascal_case_from_file_stem(&self.file_path))
                    {
                        let binding = Binding { init: Some(expr), span: node.span, annotation: None };
                        self.decline_reason = None;
                        self.argument_declined = false;
                        if let Some(mapping) = self.detect_component(&binding, &name) {
                            self.anonymous_default = Some(mapping.span_start);
                            self.data.component_mappings.push(mapping.without_binding());
                            is_a_component = true;
                        } else if self.try_record_wrapper_call(&binding, &name) {
                            self.anonymous_default = Some(node.span.start);
                            is_a_component = true;
                        }
                    }
                }
            }
        }
        // `export default React.forwardRef(Inner) as T`: the default is the component the call wraps.
        if !is_a_component
            && let Some(expression) = node.declaration.as_expression()
            && let Some(wrapped) = self.component_wrapped_by(expression)
        {
            self.record_exported_local(&wrapped, "default");
            self.record_object_assign_declarator(&wrapped, node.declaration.as_expression());
        }
        walk::walk_export_default_declaration(self, node);
    }

    fn visit_expression_statement(&mut self, node: &ExpressionStatement<'a>) {
        self.try_scan_display_name(node);
        self.try_scan_default_props(node);
        self.record_member_assignment(node);
        if self.is_tsx {
            self.try_scan_object_assign_sub_components(node);
            self.try_scan_member_assigned_sub_component(node);
        }
        walk::walk_expression_statement(self, node);
    }
}

/// The name of a function's first parameter, when it is a plain identifier (`props`).
fn first_param_name(params: &FormalParameters<'_>) -> Option<compact_str::CompactString> {
    match &params.items.first()?.pattern {
        BindingPattern::BindingIdentifier(id) => Some(id.name.as_str().into()),
        _ => None,
    }
}
