1	//! What a component's own function body does with its props, read from the syntax alone (trail 405): which props it
2	//! reads, the JSX elements it writes with their attributes in source order, and whether it hands its props object on
3	//! whole. Facts only: what they mean for which props are relevant is the resolver's to decide, and nothing here is
4	//! emitted.
5	//!
6	//! The function is the one a mapping's declaration holds, through the wrapper calls the extractor unwraps (`memo`,
7	//! `forwardRef`, a factory's first argument). A component the body declares and renders as a JSX tag
8	//! (`const Item = () => <li/>; return <Item/>`) is a component of its own: its body is not read. Elements built with
9	//! `createElement` are not recorded.
10	
11	use oxc_ast::ast::*;
12	use oxc_ast_visit::{Visit, walk};
13	use oxc_syntax::scope::ScopeFlags;
14	use rustc_hash::{FxHashMap, FxHashSet};
15	
16	use super::component::peel_expr;
17	use super::js_text;
18	use crate::types::collected::{BodyFacts, ComponentMapping, JsxAttributeFact, JsxElementFact, JsxTag, SpreadOf};
19	
20	/// Records on each mapping the facts of the function its declaration holds. A mapping with no function of its own (a
21	/// class, an alias of another component, a declaration without a body) gets none.
22	pub(super) fn attach(program: &Program<'_>, mappings: &mut [ComponentMapping]) {
23	    if mappings.is_empty() {
24	        return;
25	    }
26	    let mut finder = Finder {
27	        wanted: mappings.iter().map(|mapping| (mapping.span_start, mapping.span_end)).collect(),
28	        found: FxHashMap::default(),
29	    };
30	    finder.visit_program(program);
31	    for mapping in mappings {
32	        mapping.body = finder.found.get(&(mapping.span_start, mapping.span_end)).cloned();
33	    }
34	}
35	
36	/// A component function, by the parts the facts are read from.
37	enum ComponentFn<'b, 'a> {
38	    Function(&'b Function<'a>),
39	    Arrow(&'b ArrowFunctionExpression<'a>),
40	}
41	
42	/// The function an expression is, through parentheses, type assertions and the first argument of wrapper calls
43	/// (`memo(forwardRef((props, ref) => …))`).
44	fn unwrap<'b, 'a>(expr: &'b Expression<'a>) -> Option<ComponentFn<'b, 'a>> {
45	    match peel_expr(expr) {
46	        Expression::FunctionExpression(function) => Some(ComponentFn::Function(function)),
47	        Expression::ArrowFunctionExpression(arrow) => Some(ComponentFn::Arrow(arrow)),
48	        Expression::CallExpression(call) => unwrap(call.arguments.first()?.as_expression()?),
49	        _ => None,
50	    }
51	}
52	
53	/// Finds the nodes that start and end where a mapping does, and reads the function each holds.
54	struct Finder {
55	    wanted: FxHashSet<(u32, u32)>,
56	    found: FxHashMap<(u32, u32), BodyFacts>,
57	}
58	
59	impl Finder {
60	    fn record(&mut self, span: oxc_span::Span, function: Option<ComponentFn<'_, '_>>) {
61	        let key = (span.start, span.end);
62	        if let Some(function) = function
63	            && self.wanted.contains(&key)
64	            && !self.found.contains_key(&key)
65	        {
66	            self.found.insert(key, facts_of(&function));
67	        }
